/**
 * Read-capable state objects under a configured device whose state NEVER carried a
 * value (no value, no last-change). They are over-declarations of an earlier adapter
 * version — today's claim-with-proof creation would not make them — and deleting them
 * is lossless: there is no value and no history to lose, and anything a transport
 * legitimately claims is recreated right after, when the device connects. Runs once
 * per adapter version (the caller keeps a marker), so a freshly created state that is
 * merely waiting for its first value does not flap on every start. Excluded: buttons
 * and other write-only states (naturally valueless) and the `info.` header the adapter
 * itself maintains for every device, connected or not. A recording setting
 * (`common.custom`) is deliberately NO factor: whether anyone records a datapoint is
 * the user's business and says nothing about whether the datapoint belongs in the
 * tree — that is solely the adapter's responsibility (krobi, 2.0.3). On a never-filled
 * state there is nothing recorded to lose anyway.
 *
 * @param objects all objects under the instance, keyed by full id
 * @param states all states under the instance, keyed by full id
 * @param deviceIds the ids of the devices to sweep
 * @param namespace the adapter namespace (e.g. `yamaha.0`)
 * @returns the full ids of never-filled read-capable states
 */
export function neverWrittenStateIds(
  objects: Record<string, { type?: string; common?: unknown } | undefined>,
  states: Record<string, { val?: unknown; lc?: number } | null | undefined>,
  deviceIds: Set<string>,
  namespace: string,
): string[] {
  const ids: string[] = [];
  for (const [fullId, object] of Object.entries(objects)) {
    const common = object?.common as { read?: boolean } | undefined;
    if (object?.type !== "state" || common?.read === false) {
      continue;
    }
    const relative = stripNamespace(fullId, namespace);
    const top = relative.split(".")[0];
    if (!deviceIds.has(top) || relative.slice(top.length + 1).startsWith("info.")) {
      continue;
    }
    const state = states[fullId];
    if (!state || ((state.val === null || state.val === undefined) && !state.lc)) {
      ids.push(fullId);
    }
  }
  return ids;
}

/**
 * The full ids of renamed old states (and old channel subtrees) that still exist
 * under a configured device, to be deleted on start-up so no orphan lingers beside
 * the new object. Deepest first, so children go before their parents.
 *
 * @param existing all object ids currently under the instance
 * @param deviceIds the ids of the currently configured devices
 * @param namespace the adapter namespace (e.g. `yamaha.0`)
 * @returns the full old ids to delete, deepest first
 */
export function renamedObjectIds(existing: string[], deviceIds: Set<string>, namespace: string): string[] {
  const stale: string[] = [];
  for (const deviceId of deviceIds) {
    const base = `${namespace}.${deviceId}.`;
    for (const full of existing) {
      if (!full.startsWith(base)) {
        continue;
      }
      const rel = full.slice(base.length);
      // Strip an optional zone prefix before matching too, so one RENAMED_CHANNELS entry
      // (e.g. "straight") catches both the MAIN state and its zoned copies — the old flat
      // "zone2." form and today's "multiroom.zone2." form alike (v2.0.0 renames live in
      // zoned folders, e.g. multiroom.zone2.scene.name1).
      const zone = /^(?:multiroom\.)?zone[234]\./.exec(rel)?.[0] ?? "";
      const template = rel.slice(zone.length);
      const renamedState = RENAMED_STATE_IDS.includes(rel) || RENAMED_STATE_IDS.includes(template);
      const underRenamedChannel = RENAMED_CHANNELS.some(
        ch => rel === ch || rel.startsWith(`${ch}.`) || template === ch || template.startsWith(`${ch}.`),
      );
      if (renamedState || underRenamedChannel) {
        stale.push(full);
      }
    }
  }
  return stale.sort((a, b) => b.length - a.length);
}

/**
 * The device row to carry over from the previous adapter's single-device config,
 * or undefined if nothing needs migrating. The old yamaha stored one receiver as
 * `config.ip` (older installs: `config.IP`); the new adapter uses a `devices`
 * table. Only migrates when the table is still empty, so it runs once.
 *
 * The old value could be a hostname (its HTTP client resolved names) and could
 * carry a `:port` suffix (its HTTP library split host:port). A port suffix would
 * break every transport here — YNCA is TCP :50000, YXC/XML build `http://<ip>…`
 * — so it is stripped; the host/IP itself is carried over as-is.
 *
 * @param config the instance's native config
 * @returns the row to add to the devices table, or undefined
 */
export function legacyDeviceRow(config: Record<string, unknown>): { name: string; ip: string } | undefined {
  if (Array.isArray(config.devices) && config.devices.length > 0) {
    return undefined;
  }
  const raw =
    typeof config.ip === "string" && config.ip
      ? config.ip
      : typeof config.IP === "string" && config.IP
        ? config.IP
        : undefined;
  if (!raw) {
    return undefined;
  }
  const ip = raw.trim().replace(/:\d+$/, "");
  return ip ? { name: ip, ip } : undefined;
}

/**
 * How trustworthy a display-name candidate is. A name the device carries for itself
 * (the MusicCast zone name a user typed in the app) beats its model designation.
 */
export const LABEL_RANK = { model: 1, deviceName: 2 } as const;

/** Rank of a display-name candidate — see {@link LABEL_RANK}. */
export type LabelRank = (typeof LABEL_RANK)[keyof typeof LABEL_RANK];

/**
 * Zone names that say nothing about the device — a receiver ships with these and a
 * user who never renamed the zone would end up with "Main Zone" as the device name.
 */
const GENERIC_ZONE_NAMES = new Set(["main", "main zone", "mainzone", "zone", "zone 1", "zone1"]);

/**
 * Is this candidate worth showing as a device name?
 *
 * @param candidate the reported name
 * @returns true when it carries information about this particular device
 */
export function isUsefulDeviceName(candidate: string | undefined): boolean {
  const trimmed = (candidate ?? "").trim();
  return trimmed.length > 0 && !GENERIC_ZONE_NAMES.has(trimmed.toLowerCase());
}

/**
 * The display name to write onto a device object, or undefined to leave it alone.
 *
 * An upgraded instance carries the IP as its device name: the previous adapter knew
 * only an IP, so the migration had nothing else to call the device, and the object id
 * — which must not change, every history and visualisation binding hangs off it —
 * became that IP. This decides when the adapter may replace that placeholder with
 * something a user recognises.
 *
 * Two things must never be overwritten: a name the user typed, and a better name by a
 * weaker source. The adapter therefore only writes over its own placeholder (the id
 * itself) or over what it wrote last, and only when the new candidate ranks at least
 * as high as the one behind the current name.
 *
 * @param current the device object's present `common.name`
 * @param deviceId the object id, which is also the placeholder name
 * @param candidate the newly reported name
 * @param rank how trustworthy the candidate is
 * @param ownName the name this adapter wrote last for the device, if any
 * @param ownRank the rank behind {@link ownName}
 * @returns the name to write, or undefined when the current name stays
 */
export function nextDeviceLabel(
  current: string | undefined,
  deviceId: string,
  candidate: string | undefined,
  rank: LabelRank,
  ownName?: string,
  ownRank?: LabelRank,
): string | undefined {
  const wanted = (candidate ?? "").trim();
  if (!isUsefulDeviceName(wanted) || wanted === current) {
    return undefined;
  }
  const isPlaceholder = current === undefined || current === deviceId;
  const isOurs = ownName !== undefined && current === ownName;
  if (!isPlaceholder && !isOurs) {
    return undefined; // the user named this device — theirs wins
  }
  if (isOurs && ownRank !== undefined && rank < ownRank) {
    return undefined; // do not fall back from a device name to its model
  }
  return wanted;
}
